reactiveclass Ping(5) {
  knownrebecs { Pong pong; }
  statevars { int count; }

  Ping() {
    count = 0;
  }

  msgsrv initial() {
    // corresponds to StartMessage
    pong.PingMessage();
  }

  msgsrv PongMessage() {
    count = count + 1;
    if (count >= 10) {
      pong.StopMessage();
      // context.stop(self) has no direct equivalent; omitted
    } else {
      pong.PingMessage();
    }
  }
}

